+struct gp2ap070s_drvdata {
+	struct regmap *regmap;
+	struct mutex mutex;
+	u32 near_level;
+};
+
+static bool gp2ap070s_regmap_volatile(struct device *dev, unsigned int reg)
+{
+	return reg == GP2AP070S_REG_D0_LE16 || reg == GP2AP070S_REG_D0_LE16 + 1;
+}
